Formally in this paper, $x \in (\R_{\geq 0})^{\binom{[n]}{2}}$ is called a {\em metric} if for every distinct $i, j, k \in [n]$, $x(i, j) \leq x(i, k) + x(j, k)$.

The measure of {\em closeness} we study in this paper is the $\ell_0$ distance $\| x - y \|_0 = | \{ (i, j) \in \binom{[n]}{2} : x(i, j) \neq y(i, j) \} |$. 

Hence we study the following \mvd problem: Given $x \in \R_{\geq 0}^{\binom{[n]}{2}}$, find $y \in M_n$ that minimizes $\|x - y\|_0$, where $M_n \subseteq \R^{\binom{n}{2}}$ is the set of all metrics on $n$ points.   

$x \in \R_{\geq 0}^{\binom{n}{2}}$ is called an {\em ultrametric} if every distinct $i, j, k \in [n]$, $x(i, j) \leq \max(x(i, k), x(k, j))$. Let $U_n$ be the set of all ultrametrics on $n$ points, and \umvd be the problem, where given $x$, the goal is to find $y \in U_n$ such that $\| y - x \|_0$ is minimized. 

A \textit{triangle} is a triple of vertices, or equivalently of edges. Let $ij$ be an edge belonging to a triangle $t=ijk$. If $x(ij) > x(ik)+ x(jk)$, we say that the edge $ij$ is in \textit{excess}. If $x(ij) < |x(ik) -x(jk)|$, we say that it is in \textit{deficit}. In both cases we call the triangle $t$ \textit{unbalanced}. After pivoting at a vertex $i$, the weights of the edges adjacent to $i$ never change in the remaining recursive calls, thus we say that they are \textit{frozen}.

A hitting set for $\mathcal{T}'$ is a set of edges $H$ so that each triangle of $\mathcal{T}'$ contains at least one edge of $H$. A fractional packing for a set of triangles $\mathcal{T}'$ is a  set of values $(p_t)_{t\in \mathcal{T}'}$ so that for each edge $e$, we have $\sum_{t \ni e}p_t\leq 1$. The value of the fractional packing is $\sum_{t\in \mathcal{T'}}p_t$.

\begin{lemma}\label{L:LP}
Any solution of \mvd is at least the value of the smallest hitting set for $\mathcal{T}'$, which is itself lower bounded by the maximal value of a fractional packing of triangles in $\mathcal{T}'$.
\end{lemma}

\begin{algorithm}[h]
{\bf Input:} $n \in \N$, $x \in \R_{\gz}^{\nct}$, 
    {\bf Goal:} modify $x$ to an ultrametric.\\
    \If{$n \leq 2$}{{\bf return}}

    Choose the pivot $i \in [n]$ uniformly at random\;
    \For{$j \neq k \in [n] \setminus \{ i \}$}{
        \If{$x(i,j)=x(i,k)$}{
    $x(j, k) = \min(x(j,k),x(i,j))$;
    }
    \ElseIf{$x(j, k) \neq \max(x(i, j),x(i, k))$}{
        $x(j, k) = \max(x(i, j),x(i, k))$;
    }
    }
    \textsc{UMVD-Pivot}$(n - 1, x|_{\binom{[n]\setminus i}{2}})$ \tcp*{$x|_{\binom{[n]\setminus i}{2}}$ is $x$ restricted to $\{ (j, k) \in \binom{[n] \setminus \{ i \} }{2} \}$}
    {\bf return}
 \caption{\textsc{UMVD-Pivot}$(n, x)$}
 \label{algo:umvd}
\end{algorithm}

Consider an iteration where $i$ is chosen as the pivot. Let $x_1 < \dots < x_t$ be the distinct distances of the edges incident on $i$ (i.e. $\{ x_1, \dots, x_t \} = \{ x(i j): j \in [n] \setminus \{ i \} \}$), and for $r \in [t]$, $V_r = \{ j \in [n] \setminus \{ i \} : x(i j) = x_r \}$. Call each $V_r$ a {\em cluster}.  
Note that the algorithm ensures that, after the {\bf for} loop, 
$x(j k) = \max(x(i j), x(i k))$ if $j$ and $k$ belong to different clusters and $x(j k) \leq x(i j) = x(i k)$ if $j$ and $k$ belong to the same cluster. 

\begin{observation}\label{obs:umvd}
Any triangle that is not entirely contained in one cluster becomes balanced. 
Therefore, in the subsequent iterations, different clusters do not interact at all (e.g., having a pivot in one cluster only changes the distances within the cluster).
\end{observation}

We denote by $\mathcal{T}$ the set of all triangles, and by $\mathcal{T}'$ the set of all unbalanced triangles (i.e., a triangle such that the largest length is strictly bigger than the other two lengths). 

  \begin{lemma}\label{lem:umvd}
At each execution of a pivoting step in Algorithm~\ref{algo:umvd}, no new unbalanced triangle is created.
    \end{lemma}


